INSERT INTO server_settings (key,value,version,"updatedAt")
VALUES ('avatar.model.backfilled','{"migration":"20261018140000_avatar_model_backfill"}'::jsonb,1,CURRENT_TIMESTAMP)
ON CONFLICT (key) DO NOTHING;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM server_settings WHERE key='avatar.model.backfilled'
    AND value='{"migration":"20261018140000_avatar_model_backfill"}'::jsonb) THEN
    RAISE EXCEPTION 'avatar_backfill_marker_conflict';
  END IF;
END; $$;
COMMIT;
